import Foundation
import XCTest

@testable import FluidAudio

/// Golden test for the Swift port of Phonon's English text normalizer.
///
/// `Fixtures/phonon_normalizer_golden.json` is generated by the real Rust implementation
/// (`ptts`, `normalize_text(_, Lang::En, Rules::DEFAULT)`, `prepare_text_prompt` and
/// `split_into_best_sentences`) with `Scripts/phonon_normalizer/phonon_normalize_golden.rs`;
/// see `Scripts/phonon_normalizer/README.md` to regenerate it. Every Swift output must equal the
/// Rust output exactly.
final class PhononTextNormalizerTests: XCTestCase {

    private struct GoldenCase: Decodable {
        let input: String
        let output: String
        let prompt: String
        let framesAfterEos: Int
        let chunks50: [String]
        let chunks12: [String]
    }

    /// Inputs whose Swift output may differ from the Rust golden, with the reason. Empty: the
    /// port matches every case.
    private static let knownExceptions: [String: String] = [:]

    private func loadCases() throws -> [GoldenCase] {
        let url = try XCTUnwrap(
            Bundle.module.url(forResource: "phonon_normalizer_golden", withExtension: "json"))
        let cases = try JSONDecoder().decode([GoldenCase].self, from: Data(contentsOf: url))
        XCTAssertGreaterThanOrEqual(cases.count, 400)
        return cases
    }

    /// Compares scalar by scalar: Swift `String ==` uses canonical equivalence, which would
    /// accept e.g. a decomposed "é" for a precomposed one.
    private func scalarsEqual(_ a: String, _ b: String) -> Bool {
        a.unicodeScalars.elementsEqual(b.unicodeScalars)
    }

    func testNormalizeMatchesRustGolden() throws {
        let cases = try loadCases()
        var mismatches: [String] = []
        for golden in cases where Self.knownExceptions[golden.input] == nil {
            let actual = PhononTextNormalizer.normalize(golden.input)
            if !scalarsEqual(actual, golden.output) {
                mismatches.append(
                    "input: \(golden.input.debugDescription)\n  rust:  \(golden.output.debugDescription)\n  swift: \(actual.debugDescription)"
                )
            }
        }
        let matched = cases.count - mismatches.count - Self.knownExceptions.count
        print(
            "PhononTextNormalizer golden: \(matched)/\(cases.count) match, \(Self.knownExceptions.count) known exceptions"
        )
        XCTAssertTrue(mismatches.isEmpty, "\(mismatches.count) mismatches:\n" + mismatches.joined(separator: "\n"))
    }

    func testPrepareTextPromptMatchesRustGolden() throws {
        var mismatches: [String] = []
        for golden in try loadCases() {
            let (prompt, frames) = PhononTextNormalizer.prepareTextPrompt(golden.input)
            if !scalarsEqual(prompt, golden.prompt) || frames != golden.framesAfterEos {
                mismatches.append(
                    "input: \(golden.input.debugDescription)\n  rust:  \(golden.prompt.debugDescription) \(golden.framesAfterEos)\n  swift: \(prompt.debugDescription) \(frames)"
                )
            }
        }
        XCTAssertTrue(mismatches.isEmpty, "\(mismatches.count) mismatches:\n" + mismatches.joined(separator: "\n"))
    }

    /// The chunker is compared under the same deterministic toy tokenizer as the Rust generator,
    /// so the sentence splitting and greedy grouping are what is tested, at a budget of 50
    /// tokens (the default) and of 12 (to force grouping decisions).
    func testChunkerMatchesRustGolden() throws {
        var mismatches: [String] = []
        for golden in try loadCases() {
            for (budget, expected) in [(50, golden.chunks50), (12, golden.chunks12)] {
                let actual = try PhononTextChunker.splitIntoBestSentences(
                    golden.output, tokenizer: ToyTokenizer(), maxTokens: budget)
                let same = actual.count == expected.count && zip(actual, expected).allSatisfy(scalarsEqual)
                if !same {
                    mismatches.append(
                        "input: \(golden.output.debugDescription) @\(budget)\n  rust:  \(expected)\n  swift: \(actual)")
                }
            }
        }
        XCTAssertTrue(mismatches.isEmpty, "\(mismatches.count) mismatches:\n" + mismatches.joined(separator: "\n"))
    }

    func testChunkNormalizesFirst() throws {
        let chunks = try PhononTextChunker.chunk("It costs $5. Call 555-123-4567!", tokenizer: ToyTokenizer())
        XCTAssertEqual(chunks, ["It costs 5 dollars. Call 555 123 4 5 6 7!"])
    }
}

/// The toy tokenizer of `phonon_normalize_golden.rs`: a maximal run of alphanumeric scalars,
/// or any other single non-space scalar, each taking one preceding space with it; a space before
/// another space or at the end is a piece of its own. Ids are handed out in order of first
/// appearance; decoding concatenates the pieces and drops one leading space.
private final class ToyTokenizer: PhononChunkTokenizer {
    private var ids: [[UInt32]: Int] = [:]
    private var pieces: [String] = []

    private func id(_ piece: [Unicode.Scalar]) -> Int {
        let key = piece.map(\.value)
        if let id = ids[key] { return id }
        let id = pieces.count
        var view = String.UnicodeScalarView()
        view.append(contentsOf: piece)
        pieces.append(String(view))
        ids[key] = id
        return id
    }

    func encode(_ text: String) throws -> [Int] {
        let chars = Array(text.unicodeScalars)
        var out: [Int] = []
        var i = 0
        while i < chars.count {
            var piece: [Unicode.Scalar] = []
            if chars[i] == " " {
                piece.append(" ")
                i += 1
                if i >= chars.count || chars[i] == " " {
                    out.append(id(piece))
                    continue
                }
            }
            if PhononScalar.isAlphanumeric(chars[i]) {
                while i < chars.count, PhononScalar.isAlphanumeric(chars[i]) {
                    piece.append(chars[i])
                    i += 1
                }
            } else {
                piece.append(chars[i])
                i += 1
            }
            out.append(id(piece))
        }
        return out
    }

    func decode(_ tokens: [Int]) throws -> String {
        var scalars = String.UnicodeScalarView()
        for token in tokens {
            scalars.append(contentsOf: pieces[token].unicodeScalars)
        }
        if scalars.first == " " { scalars.removeFirst() }
        return String(scalars)
    }
}
